// Dense RGBA adaptation of legacy/core/animation-thumbnail.ts and raster bounds/read.
#include "cel_thumbnail.h"
#include <algorithm>
#include <cmath>
#include <limits>
#include <optional>
#include <stdexcept>
namespace moon {namespace {
using Pixel=timeline::Pixel;
struct Rect {double x,y,width,height;};
double pixelPerfectScale(double scale){if(!std::isfinite(scale)||scale<=0)return 1;return scale>=1?std::max(1.0,std::floor(scale)):1/std::ceil(1/scale);}
Pixel readLocal(const timeline::Surface& s,int x,int y){if(x<0||y<0||x>=s.width||y>=s.height)return 0;auto index=std::size_t(y)*s.width+x;return index<s.pixels.size()?s.pixels[index]:0;}
std::optional<Rect> contentBounds(const timeline::Surface& s){int minX=s.width,minY=s.height,maxX=-1,maxY=-1;for(int y=0;y<s.height;++y){int left=0;while(left<s.width&&!(readLocal(s,left,y)>>24))++left;if(left==s.width)continue;minX=std::min(minX,left);minY=std::min(minY,y);maxY=y;int right=s.width-1;while(right>maxX&&right>left&&!(readLocal(s,right,y)>>24))--right;maxX=std::max(maxX,right);}if(maxX<minX||maxY<minY)return {};return Rect{double(minX),double(minY),double(maxX-minX+1),double(maxY-minY+1)};}
Rect canvasLayout(int documentWidth,int documentHeight,int size,const timeline::Surface& s,const std::optional<Rect>& content){double width=std::max(1,documentWidth),height=std::max(1,documentHeight),safeSize=std::max(1,size),fit=std::min(safeSize/width,safeSize/height),padding=std::min(6.0,std::max(2.0,safeSize/10));double contentScale=content?std::min((safeSize-padding*2)/std::max(1.0,content->width),(safeSize-padding*2)/std::max(1.0,content->height)):fit;double scale=pixelPerfectScale(std::max(fit,contentScale)),centerX=content?double(s.offsetX)+content->x+content->width/2:width/2,centerY=content?double(s.offsetY)+content->y+content->height/2:height/2;return {safeSize/2-centerX*scale,safeSize/2-centerY*scale,width*scale,height*scale};}
unsigned roundedByte(double value){return unsigned(std::floor(value+.5));}
Pixel blendChecker(Pixel bottom,Pixel source,double alpha){alpha=std::clamp(alpha,0.0,1.0);if(alpha<=0)return bottom;if(alpha>=1)return source|0xff000000u;Pixel result=0xff000000u;for(int shift:{0,8,16})result|=Pixel(roundedByte(((source>>shift)&255)*alpha+((bottom>>shift)&255)*(1-alpha)))<<shift;return result;}
}
std::vector<timeline::Pixel> renderCelThumbnailPixels(int canvasWidth,int canvasHeight,const timeline::Surface& surface,const CelThumbnailOptions& options){if(!std::isfinite(options.targetSize))throw std::invalid_argument("Invalid thumbnail size");double truncated=std::max(1.0,std::trunc(options.targetSize));if(truncated>std::numeric_limits<int>::max())throw std::length_error("Thumbnail too large");int size=int(truncated);auto count=std::uint64_t(size)*size;if(count>std::vector<Pixel>().max_size())throw std::length_error("Thumbnail too large");std::vector<Pixel> output(std::size_t(count),0);bool transparent=options.background==CelThumbnailBackground::Transparent;if(!transparent){int checkerSize=std::max(2,int(std::floor(double(size)/8+.5)));for(int y=0;y<size;++y)for(int x=0;x<size;++x)output[std::size_t(y)*size+x]=((x/checkerSize+y/checkerSize)%2==0)?0xffa1968fu:0xffd6cec9u;}if(surface.width<1||surface.height<1)return output;if(std::uint64_t(surface.width)*surface.height>9007199254740991ULL/4)return output;auto content=options.framing==CelThumbnailFraming::Canvas?std::optional<Rect>{}:contentBounds(surface);auto layout=canvasLayout(canvasWidth,canvasHeight,size,surface,content);double scale=layout.width/std::max(1,canvasWidth);if(!std::isfinite(scale)||scale<=0)return output;double opacity=std::clamp(std::isfinite(options.opacity)?options.opacity:1.0,0.0,1.0);int width=std::max(1,canvasWidth),height=std::max(1,canvasHeight);for(int y=0;y<size;++y)for(int x=0;x<size;++x){double canvasX=(x+.5-layout.x)/scale,canvasY=(y+.5-layout.y)/scale;if(canvasX<0||canvasY<0||canvasX>=width||canvasY>=height)continue;double sourceX=std::floor(canvasX-double(surface.offsetX)),sourceY=std::floor(canvasY-double(surface.offsetY));if(sourceX<0||sourceY<0||sourceX>=surface.width||sourceY>=surface.height)continue;auto source=readLocal(surface,int(sourceX),int(sourceY));double alpha=double(source>>24)/255;auto index=std::size_t(y)*size+x;if(transparent)output[index]=(source&0x00ffffffu)|(Pixel(roundedByte(alpha*opacity*255))<<24);else output[index]=blendChecker(output[index],source,alpha*opacity);}return output;}
}
